// config/secrets.js
const dotenv = require('dotenv');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const fs = require('fs');
const path = require('path');

// Load .env file only in development
if (process.env.NODE_ENV !== 'production') {
  const envPath = path.resolve(process.cwd(), '.env');
  if (fs.existsSync(envPath)) {
    dotenv.config({ path: envPath });
  }
}

/**
 * Securely retrieve secrets from environment or AWS Secrets Manager
 */
class SecretManager {
  constructor() {
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1',
      // In production, use IAM roles instead of hardcoded credentials
      ...(process.env.AWS_ACCESS_KEY_ID && {
        credentials: {
          accessKeyId: process.env.AWS_ACCESS_KEY_ID,
          secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
        }
      })
    });
    this.cache = new Map();
  }

  /**
   * Get secret value with validation
   */
  async getSecret(secretName, required = true) {
    // Check cache first
    if (this.cache.has(secretName)) {
      return this.cache.get(secretName);
    }

    // Try environment variable first (more secure for containers)
    const envVar = secretName.toUpperCase().replace(/-/g, '_');
    if (process.env[envVar]) {
      return process.env[envVar];
    }

    // In production, fetch from AWS Secrets Manager
    if (process.env.NODE_ENV === 'production') {
      try {
        const command = new GetSecretValueCommand({ SecretId: secretName });
        const response = await this.client.send(command);
        const secret = JSON.parse(response.SecretString);
        this.cache.set(secretName, secret);
        return secret;
      } catch (error) {
        if (required) {
          throw new Error(`Required secret "${secretName}" not found`);
        }
        return undefined;
      }
    }

    // Fail if required secret is missing
    if (required) {
      throw new Error(`Required secret "${secretName}" not configured`);
    }
    return undefined;
  }

  /**
   * Validate all required secrets on startup
   */
  async validateRequiredSecrets() {
    const required = [
      'DATABASE_URL',
      'JWT_SECRET',
      'ENCRYPTION_KEY'
    ];

    const missing = [];
    for (const secret of required) {
      try {
        await this.getSecret(secret);
      } catch {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }
}

const secrets = new SecretManager();

module.exports = { secrets };
```

