### 🛡️ Security Recommendations for Secrets Management

#### 1. **Add dotenv to load .env files (Development Only)**

```javascript
require('dotenv').config();

// Now use: process.env.DATABASE_URL, etc.
```

#### 2. **Use Environment-Specific Loading**

```javascript
// config.js
const dotenv = require('dotenv');
const path = require('path');

// Load environment-specific .env file
const envFile = process.env.NODE_ENV === 'production' 
  ? '.env.production' 
  : '.env.development';

dotenv.config({ path: path.resolve(process.cwd(), envFile) });
```

#### 3. **Production: Use a Secrets Manager** (Recommended)

For production, avoid .env files entirely. Use a secrets manager:

```javascript
// Option A: AWS Secrets Manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function getSecret(secretName) {
  const client = new SecretsManagerClient({ region: 'us-east-1' });
  const response = await client.send(new GetSecretValueCommand({ SecretId: secretName }));
  return JSON.parse(response.SecretString);
}

// Option B: HashiCorp Vault
const vault = require('node-vault')({ endpoint: 'https://vault.example.com' });
await vault.oktaLogin({ role: 'my-app', secret: process.env.VAULT_SECRET });
const { db_password } = await vault.read('secret/data/my-app/db');
```

#### 4. **Never Hardcode Secrets**

```javascript
